// Paths CLAUDE.md does not hold to ASCII, each with its reason.
const excludedPrefixes: readonly string[] = [
  // Quoted game text and rule catalogs.
  'docs/game-rules/',
  // Agent steering: output templates use marker symbols.
  '.claude/',
  '.github/agents/',
  '.github/skills/',
  '.github/instructions/',
  '.github/copilot-instructions.md',
]

// Generated by npm.
const excludedFileNames: readonly string[] = ['package-lock.json']

// Baseline: files with non-ASCII text that predate this check. Shrink this list; do not grow it.
const baselineFiles: ReadonlySet<string> = new Set([
  // UI copy with an ellipsis; changing it changes what users see.
  'frontend/src/campaign-play/components/attention-list/attention-list.tsx',
  'frontend/src/campaign-play/components/create-campaign-form/create-campaign-form.tsx',
  'frontend/src/campaign-play/components/invite-management/invite-management.tsx',
  'frontend/src/campaign-play/components/join-campaign/join-campaign.tsx',
  'frontend/src/campaign-play/components/rules-options/rules-options.tsx',
  'frontend/src/campaign-play/components/start-over-dialog/start-over-dialog.tsx',
  // Prose and comments.
  'docs/adr/0001-persist-account-entity.md',
  'e2e/CLAUDE.md',
  'e2e/tests/invite-management.spec.ts',
  'e2e/tests/player-join.spec.ts',
  'specs/identity-and-access/spec.md',
])

export function isScanned(path: string): boolean {
  const fileName = path.slice(path.lastIndexOf('/') + 1)
  return (
    !excludedPrefixes.some((prefix) => path.startsWith(prefix)) &&
    !excludedFileNames.includes(fileName) &&
    !baselineFiles.has(path)
  )
}
